import { Entity, Index, ManyToOne, PrimaryKey, Property } from "@mikro-orm/core";
import { randomUUID } from "node:crypto";
import { Game } from "./Game.js";
import { User } from "./User.js";

/**
 * "system" posts are generated by the platform, e.g. when a game is hosted.
 * "recap" posts are generated after a game ends; see recaps.ts.
 */
export const POST_KINDS = ["user", "system", "recap"] as const;
export type PostKind = (typeof POST_KINDS)[number];

export const POST_MAX_LEN = 500;
export const POST_MAX_IMAGES = 4;

/**
 * A Pro market shared in a post (api/markets). Filled in by the server from
 * Gemini's catalog when the post is written; the author only names the
 * contract and side, never the price, and the post never says how much the
 * author holds.
 */
export interface PostMarket {
  ticker: string;
  symbol: string;
  title: string;
  label: string;
  outcome: "yes" | "no";
  /** The buy price when the post was written, 0–1. */
  price: string | null;
  league: string;
  sport: string;
  /** Set when the market had already settled as the post was written: how the shared side did. */
  result?: "won" | "lost" | null;
}

@Entity({ tableName: "posts" })
@Index({ properties: ["createdAt"] })
@Index({ properties: ["author", "createdAt"] })
@Index({ properties: ["sport", "createdAt"] })
export class Post {
  @PrimaryKey({ type: "uuid" })
  id: string = randomUUID();

  @ManyToOne(() => User, { deleteRule: "cascade" })
  author!: User;

  @Property({ type: "text" })
  body!: string;

  @Property({ type: "string", length: 16 })
  kind: PostKind = "user";

  /** Attached images, as /uploads/... URLs. Empty for text-only posts. */
  @Property({ type: "json", defaultRaw: "'[]'::jsonb" })
  images: string[] = [];

  /** Set when the post is about a game, which renders an inline game card. */
  @ManyToOne(() => Game, { nullable: true, deleteRule: "set null" })
  game?: Game | null;

  @ManyToOne(() => Post, { nullable: true, deleteRule: "cascade" })
  replyTo?: Post | null;

  /**
   * The sport the post is about, so a sport page can show it: the attached
   * game's sport, the shared market's, or the one the author posted under.
   */
  @Property({ type: "string", length: 24, nullable: true })
  sport?: string | null;

  /** Set when the post shares a Pro market; see PostMarket. */
  @Property({ type: "json", nullable: true })
  market?: PostMarket | null;

  // Denormalised so a timeline read stays one query per page.
  @Property({ type: "int" })
  likeCount: number = 0;

  @Property({ type: "int" })
  replyCount: number = 0;

  @Property({ type: "timestamptz", onCreate: () => new Date() })
  createdAt: Date = new Date();
}
